Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, POPCNT[MAX_SIZE], F[MAX_SIZE];
int A[20][MAX_SIZE], B[20][MAX_SIZE], C[20][MAX_SIZE];
long long MOD_SQUARED;
long long TEMP[20][MAX_SIZE];
long long FACTORIALS[MAX_SIZE], INVERSE_FACTORS[MAX_SIZE];

long long modular_exponentiation(long long base, long long exponent) {
    long long result = 1;
    base %= MOD;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return result;
}

void initialize_factorials() {
    FACTORIALS[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        FACTORIALS[i] = FACTORIALS[i-1] * i % MOD;
    INVERSE_FACTORS[MAX_VAL] = modular_exponentiation(FACTORIALS[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        INVERSE_FACTORS[i] = INVERSE_FACTORS[i+1] * (i+1) % MOD;
}

int smallest_power_of_two(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void walsh_transform(int *array, int size, bool is_inverse = false) {
    static long long temp_buffer[MAX_SIZE];
    for (int i = 0; i < size; ++i) temp_buffer[i] = array[i];

    if (is_inverse) {
        for (int segment = 1; segment < size; segment <<= 1) {
            for (int i = 0; i < size; i += segment << 1) {
                for (int j = 0; j < segment; ++j) {
                    temp_buffer[i + segment + j] = (temp_buffer[i + segment + j] - temp_buffer[i + j]) % MOD;
                }
            }
        }
    } else {
        for (int segment = 1; segment < size; segment <<= 1) {
            for (int i = 0; i < size; i += segment << 1) {
                for (int j = 0; j < segment; ++j) {
                    temp_buffer[i + segment + j] = (temp_buffer[i + segment + j] + temp_buffer[i + j]) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < size; ++i) {
        array[i] = (int)(temp_buffer[i] % MOD);
        if (array[i] < 0) array[i] += MOD;
    }
}

inline void adjust_mod(long long &value) {
    if (value >= MOD_SQUARED) value -= MOD_SQUARED;
}

void perform_multiplication() {
    for (int i = 0; i <= 19; ++i) {
        memset(A[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(TEMP[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        A[POPCNT[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        walsh_transform(A[i], MAX_VAL + 1);

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                adjust_mod(TEMP[i + j][idx] += 1LL * A[i][idx] * B[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            C[i][idx] = (int)(TEMP[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        walsh_transform(C[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        F[i] = C[POPCNT[i]][i];
}

void perform_squaring() {
    static int buffer[20][MAX_SIZE];
    for (int i = 0; i <= 19; ++i)
        memset(TEMP[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                adjust_mod(TEMP[i + j][idx] += 1LL * B[i][idx] * B[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            buffer[i][idx] = (int)(TEMP[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        walsh_transform(buffer[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(B[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int idx = 0; idx <= MAX_VAL; ++idx)
        B[POPCNT[idx]][idx] = buffer[POPCNT[idx]][idx];

    for (int i = 0; i <= 19; ++i)
        walsh_transform(B[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQUARED = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", modular_exponentiation(K, N));
        return 0;
    }

    F[0] = 1;
    MAX_VAL = smallest_power_of_two(N + 1) - 1;
    initialize_factorials();

    for (int i = 0; i <= MAX_VAL; ++i)
        POPCNT[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        B[POPCNT[i]][i] = INVERSE_FACTORS[i];

    for (int i = 0; i <= 19; ++i)
        walsh_transform(B[i], MAX_VAL + 1);

    int original_k = K;
    while (K) {
        if (K & 1) perform_multiplication();
        K >>= 1;
        if (K) perform_squaring();
    }

    long long final_result = (modular_exponentiation(original_k, N) - FACTORIALS[N] * F[N] % MOD + MOD) % MOD;
    printf("%lld", final_result);
    return 0;
}
